#include <bits/stdc++.h>
using namespace std;const int N=100000;int p[N],h[N+5],e[3][N],n;bool v[N+5];long long P,M,r[3];long long z(long long x){x%=M;return x<0?x+M:x;}long long s(long long x){long long a=x,b=x+1;if(a&1)b/=2;else a/=2;return a%M*(b%M)%M;}long long E(int q,int a,int b,int c){long long x=0,y=0,u=0,w=0,t=q,L=max(a,max(b,c));while(t<=L){long long A=a/t,B=b/t,C=c/t;x=(x+A)%M;y=(y+B)%M;u=(u+A%M*(B%M))%M;w=(w+A%M*(C%M))%M;if(t>L/q)break;t*=q;}return z(b%M*(c%M)%M*x+a%M*(c%M)%M*y-c%M*u-b%M*w);}long long F(int q,int a,int b,int c){long long x=0,y=0,u=0,w=0,t=q,L=max(a,max(b,c));while(t<=L){long long A=t%M*s(a/t)%M,B=t%M*s(b/t)%M,C=t%M*s(c/t)%M;x=(x+A)%M;y=(y+B)%M;u=(u+A*B)%M;w=(w+A*C)%M;if(t>L/q)break;t*=q;}return z(s(b)*s(c)%M*x+s(a)*s(c)%M*y-s(c)*u-s(b)*w);}long long k(long long a,long long b){long long r=1;for(;b;b>>=1,a=a*a%P)if(b&1)r=r*a%P;return r;}int main(){ios::sync_with_stdio(0);cin.tie(0);h[1]=1;for(int i=2;i<=N;i++){if(!v[i])p[n++]=i,h[i]=i-1;for(int j=0;j<n&&i*p[j]<=N;j++){v[i*p[j]]=1;if(i%p[j]==0){h[i*p[j]]=h[i]*p[j];break;}h[i*p[j]]=h[i]*(p[j]-1);}}int T;cin>>T>>P;M=P-1;while(T--){int a,b,c;cin>>a>>b>>c;int L=max(a,b);for(int i=0;i<n&&p[i]<=L;i++)e[0][i]=E(p[i],a,b,c),e[1][i]=F(p[i],a,b,c),e[2][i]=0;for(int d=1;d<=min(a,min(b,c));d++){int x=a/d,y=b/d,z=c/d,l=max(x,y);for(int i=0;i<n&&p[i]<=l;i++)e[2][i]=(e[2][i]+h[d]%M*E(p[i],x,y,z))%M;}for(int j=0;j<3;j++)r[j]=1;for(int i=0;i<n&&p[i]<=L;i++)for(int j=0;j<3;j++)r[j]=r[j]*k(p[i],e[j][i])%P;cout<<r[0]<<' '<<r[1]<<' '<<r[2]<<'\n';}}
